SELECT *, AVG(monthly_fee) OVER (PARTITION BY plan, status ORDER BY monthly_fee, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) monthly_fee_avg_2, SUM(monthly_fee) OVER (PARTITION BY customer_id ORDER BY start_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_monthly_fee, AVG(monthly_fee) OVER (PARTITION BY status, plan ORDER BY monthly_fee, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) monthly_fee_avg_2_prior, SUM(monthly_fee) OVER (PARTITION BY status ORDER BY start_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_monthly_fee_2, NTILE(3) OVER (PARTITION BY plan ORDER BY monthly_fee, id) monthly_fee_bucket FROM subscriptions;
